```
module apb_cdc #(
    parameter ADDR_WIDTH = 8,
    parameter DATA_WIDTH = 32,
    parameter LOG_DEPTH = 1
)(
    input                      src_pclk_i,
    input                      src_preset_ni,
    input                      src_psel_i,
    input                      src_penable_i,
    input                      src_pwrite_i,
    input  [ADDR_WIDTH-1:0]    src_paddr_i,
    input  [DATA_WIDTH-1:0]    src_pwdata_i,
    input  [DATA_WIDTH/8-1:0]  src_pstrb_i,
    input  [2:0]               src_pprot_i,
    output                     src_pready_o,
    output [DATA_WIDTH-1:0]    src_prdata_o,
    output                     src_pslverr_o,
    input                      dst_pclk_i,
    input                      dst_preset_ni,
    output                     dst_psel_o,
    output                     dst_penable_o,
    output                     dst_pwrite_o,
    output [ADDR_WIDTH-1:0]    dst_paddr_o,
    output [DATA_WIDTH-1:0]    dst_pwdata_o,
    output [DATA_WIDTH/8-1:0]  dst_pstrb_o,
    output [2:0]               dst_pprot_o,
    input                      dst_pready_i,
    input  [DATA_WIDTH-1:0]    dst_prdata_i,
    input                      dst_pslverr_i
);

    // Internal signals
    reg [DATA_WIDTH-1:0] src_pwdata_reg;
    reg [DATA_WIDTH/8-1:0] src_pstrb_reg;
    reg [2:0] src_pprot_reg;
    reg src_pwrite_reg;
    reg src_psel_reg;
    reg src_penable_reg;
    reg [ADDR_WIDTH-1:0] src_paddr_reg;
    reg src_pready_reg;
    reg [DATA_WIDTH-1:0] dst_prdata_reg;
    reg dst_pslverr_reg;
    reg dst_pwrite_reg;
    reg dst_psel_reg;
    reg dst_penable_reg;
    reg [ADDR_WIDTH-1:0] dst_paddr_reg;
    reg [DATA_WIDTH-1:0] dst_pwdata_reg;
    reg [DATA_WIDTH/8-1:0] dst_pstrb_reg;
    reg [2:0] dst_pprot_reg;
    reg dst_pready_reg;

    // Clock domain crossing FIFOs
    reg [DATA_WIDTH-1:0] src_fifo [0:2**LOG_DEPTH-1];
    reg [DATA_WIDTH/8-1:0] src_fifo_strb [0:2**LOG_DEPTH-1];
    reg [2:0] src_fifo_prot [0:2**LOG_DEPTH-1];
    reg [ADDR_WIDTH-1:0] src_fifo_addr [0:2**LOG_DEPTH-1];
    reg [DATA_WIDTH-1:0] dst_fifo [0:2**LOG_DEPTH-1];
    reg [DATA_WIDTH/8-1:0] dst_fifo_strb [0:2**LOG_DEPTH-1];
    reg [2:0] dst_fifo_prot [0:2**LOG_DEPTH-1];
    reg [ADDR_WIDTH-1:0] dst_fifo_addr [0:2**LOG_DEPTH-1];
    reg [LOG_DEPTH-1:0] src_fifo_head;
    reg [LOG_DEPTH-1:0] src_fifo_tail;
    reg [LOG_DEPTH-1:0] dst_fifo_head;
    reg [LOG_DEPTH-1:0] dst_fifo_tail;
    reg src_fifo_full;
    reg dst_fifo_full;
    reg src_fifo_empty;
    reg dst_fifo_empty;

    // Clock domain crossing FIFO write
    always @(posedge src_pclk_i) begin
        if (!src_preset_ni) begin
            src_fifo_head <= 0;
            src_fifo_tail <= 0;
            src_fifo_full <= 0;
            src_fifo_empty <= 1;
        end else begin
            if (src_penable_reg && src_pready_reg) begin
                if (!src_fifo_full) begin
                    src_fifo[src_fifo_head] <= src_pwdata_i;
                    src_fifo_strb[src_fifo_head] <= src_pstrb_i;
                    src_fifo_prot[src_fifo_head] <= src_pprot_i;
                    src_fifo_addr[src_fifo_head] <= src_paddr_i;
                    src_fifo_head <= src_fifo_head + 1;
                    if (src_fifo_head == src_fifo_tail) begin
                        src_fifo_full <= 1;
                    end
                    src_fifo_empty <= 0;
                end
            end
        end
    end

    // Clock domain crossing FIFO read
    always @(posedge dst_pclk_i) begin
        if (!dst_preset_ni) begin
            dst_fifo_head <= 0;
            dst_fifo_tail <= 0;
            dst_fifo_full <= 0;
            dst_fifo_empty <= 1;
        end else begin
            if (dst_penable_reg && dst_pready_reg) begin
                if (!dst_fifo_empty) begin
                    dst_prdata_reg <= dst_fifo[dst_fifo_tail];
                    dst_pslverr_reg <= dst_fifo_strb[dst_fifo_tail][0];
                    dst_pwrite_reg <= dst_fifo_strb[dst_fifo_tail][1];
                    dst_psel_reg <= dst_fifo_strb[dst_fifo_tail][2];
                    dst_penable_reg <= 1;
                    dst_paddr_reg <= dst_fifo_addr[dst_fifo_tail];
                    dst_pwdata_reg <= dst_fifo[dst_fifo_tail];
                    dst_pstrb_reg <= dst_fifo_strb[dst_fifo_tail];
                    dst_pprot_reg <= dst_fifo_prot[dst_fifo_tail];
                    dst_fifo_tail <= dst_fifo_tail + 1;
                    if (dst_fifo_tail == dst_fifo_head) begin
                        dst_fifo_empty <= 1;
                    end
                    dst_fifo_full <= 0;
                end else begin
                    dst_penable_reg <= 0;
                end
            end
        end
    end

    // Clock domain crossing FIFO status
    always @(posedge src_pclk_i) begin
        if (!src_preset_ni) begin
            src_fifo_full <= 0;
            src_fifo_empty <= 1;
        end else begin
            if (src_penable_reg && src_pready_reg) begin
                if (src_fifo_head == src_fifo_tail) begin
                    src_fifo_full <= 1;
                end else begin
                    src_fifo_full <= 0;
                end
                if (src_fifo_head == src_fifo_tail) begin
                    src_fifo_empty <= 1;
                end else begin
                    src_fifo_empty <= 0;
                end
            end
        end
    end

    // Clock domain crossing FIFO status
    always @(posedge dst_pclk_i) begin
        if (!dst_preset_ni) begin
            dst_fifo_full <= 0;
            dst_fifo_empty <= 1;
        end else begin
            if (dst_penable_reg && dst_pready_reg) begin
                if (dst_fifo_head == dst_fifo_tail) begin
                    dst_fifo_full <= 1;
                end else begin
                    dst_fifo_full <= 0;
                end
                if (dst_fifo_head == dst_fifo_tail) begin
                    dst_fifo_empty <= 1;
                end else begin
                    dst_fifo_empty <= 0;
                end
            end
        end
    end

    // APB slave interface
    always @(posedge src_pclk_i) begin
        if (!src_preset_ni) begin
            src_pready_reg <= 0;
            src_prdata_o <= 0;
            src_pslverr_o <= 0;
        end else begin
            if (src_psel_i && src_penable_i) begin
                src_pready_reg <= 0;
                src_prdata_o <= 0;
                src_pslverr_o <= 0;
            end else if (src_psel_i && !src_penable_i) begin
                src_pready_reg <= 1;
                src_prdata_o <= dst_prdata_reg;
                src_pslverr_o <= dst_pslverr_reg;
            end else begin
                src_pready_reg <= 0;
                src_prdata_o <= 0;
                src_pslverr_o <= 0;
            end
        end
    end

    // APB master interface
    always @(posedge dst_pclk_i) begin
        if (!dst_preset_ni) begin
            dst_psel_o <= 0;
            dst_penable_o <= 0;
            dst_pwrite_o <= 0;
            dst_paddr_o <= 0;
            dst_pwdata_o <= 0;
            dst_pstrb_o <= 0;
            dst_pprot_o <= 0;
        end else begin
            if (dst_psel_reg && dst_penable_reg) begin
                dst_psel_o <= 1;
                dst_penable_o <= 1;
                dst_pwrite_o <= src_pwrite_reg;
                dst_paddr_o <= src_paddr_i;
                dst_pwdata_o <= src_pwdata_i;
                dst_pstrb_o <= src_pstrb_i;
                dst_pprot_o <= src_pprot_i;
            end else begin
                dst_psel_o <= 0;
                dst_penable_o <= 0;
                dst_pwrite_o <= 0;
                dst_paddr_o <= 0;
                dst_pwdata_o <= 0;
                dst_pstrb_o <= 0;
                dst_pprot_o <= 0;
            end
        end
    end

